let ownerProbe = new Ranvier.Owner();;
let cleanupProbe = ResizeArray<string>();;
ownerProbe.OnCleanup(System.Action(fun () -> cleanupProbe.Add("first")));;
ownerProbe.OnCleanup(System.Action(fun () -> cleanupProbe.Add("second")));;
ownerProbe.Attach({ new System.IDisposable with member _.Dispose() = cleanupProbe.Add("child") });;
ownerProbe.Dispose();;
ownerProbe.Dispose();;
ownerProbe.OnCleanup(System.Action(fun () -> cleanupProbe.Add("late-cleanup")));;
ownerProbe.Attach({ new System.IDisposable with member _.Dispose() = cleanupProbe.Add("late-child") });;
(ownerProbe.IsDisposed, cleanupProbe.ToArray(), ownerProbe.ErrorCount);;

