let coreGraphProbe = new Ranvier.Graph();;
let coreGraphActivationProbe = coreGraphProbe.Activate();;
let effectReadsProbe = ResizeArray<float>();;
let effectOwnerProbe, targetSignalProbe = Ranvier.Api.createRoot(fun owner -> let signal = Ranvier.Api.createSignal 0. in Ranvier.Api.createEffect(fun () -> effectReadsProbe.Add(signal.Value)); owner, signal);;
coreGraphProbe.Flush();;
targetSignalProbe.Value <- 10.;;
coreGraphProbe.Flush();;
effectOwnerProbe.Dispose();;
targetSignalProbe.Value <- 20.;;
coreGraphProbe.Flush();;
effectReadsProbe.ToArray();;
